WITH bounds AS (
  SELECT greatest(min(window_start), date_trunc('minute', $__timeFrom()::timestamptz)) AS lo,
         least(max(window_end), $__timeTo()::timestamptz) AS hi
  FROM public.ark_usage_exports WHERE account_id IN (${account:sqlstring})
), minutes AS (
  SELECT generate_series(lo, hi - interval '1 microsecond', interval '1 minute') AS time FROM bounds
), models AS (
  SELECT DISTINCT model_name FROM public.ark_usage_records WHERE account_id IN (${account:sqlstring}) AND model_name IN (${model:sqlstring})
), samples AS (
  SELECT minute_start, model_name, sum(total_tokens) AS value
  FROM public.ark_model_tpm WHERE account_id IN (${account:sqlstring}) AND model_name IN (${model:sqlstring}) AND minute_start >= $__timeFrom()::timestamptz AND minute_start < $__timeTo()::timestamptz GROUP BY 1, 2
)
SELECT minutes.time, models.model_name AS metric, coalesce(samples.value, 0) / 10000.0 AS value
FROM minutes CROSS JOIN models
LEFT JOIN samples ON samples.minute_start = minutes.time AND samples.model_name = models.model_name
ORDER BY 1, 2;

